  const Ctor = BOSS_TYPES[spec.type] || MossGolem;
  return new Ctor(game, spec);
}

export function disposeBoss(boss) {
  if (!boss) return;
  boss.game.scene.remove(boss.group);
  disposeGroup(boss.group);
