106: /* ============================================================
107:    Training wisp — a small practice target near the Dawn Shrine.
108:    These are not enemies; they simply prove the combo and lock-on.
109:    ============================================================ */
110: class TrainingWisp {
111:   constructor(scene, position, { color = 0xffd98a, phase = 0 } = {}) {
112:     this.scene = scene;
113:     this.home = position.clone();
114:     this.position = position.clone();
115:     this.color = color;
116:     this.phase = phase;
117:     this.alive = true;
118:     this.cooldown = 0;
119:     this.time = phase;
120:     this.radius = 0.55;
121: 
122:     const group = new THREE.Group();
123:     group.position.copy(position);
124:     this.group = group;
125: 
126:     this.coreMat = new THREE.MeshStandardMaterial({
127:       color,
128:       emissive: new THREE.Color(color).multiplyScalar(0.55),
129:       emissiveIntensity: 1.6,
130:       metalness: 0.2,
131:       roughness: 0.16,
132:       transparent: true,
133:       opacity: 0.94,
134:     });
135:     this.core = new THREE.Mesh(new THREE.OctahedronGeometry(0.32, 0), this.coreMat);
136:     this.core.castShadow = true;
137:     group.add(this.core);
138: 
139:     this.ringMat = new THREE.MeshBasicMaterial({
140:       color,
141:       transparent: true,
142:       opacity: 0.4,
143:       blending: THREE.AdditiveBlending,
144:       depthWrite: false,
145:       toneMapped: false,
146:     });
147:     this.ring = new THREE.Mesh(new THREE.TorusGeometry(0.62, 0.022, 4, 32), this.ringMat);
148:     this.ring.rotation.x = Math.PI / 2.4;
149:     group.add(this.ring);
150: 
151:     this.glow = makeGlowSprite({ color, size: 2.2, opacity: 0.4, texture: WISP_GLOW });
152:     group.add(this.glow);
153: 
154:     this.light = new THREE.PointLight(color, 0.9, 8, 2);
155:     group.add(this.light);
156: 
157:     scene.add(group);
158:   }
159: 
160:   get center() {
161:     return this.position.clone().add(new THREE.Vector3(0, 0.95, 0));
162:   }
163: 
164:   tryHit(playerPos, facing) {
165:     if (!this.alive) return false;
166:     const dx = this.position.x - playerPos.x;
167:     const dz = this.position.z - playerPos.z;
168:     const dist = Math.hypot(dx, dz);
169:     if (dist > 2.7 || Math.abs(this.position.y - playerPos.y) > 2.2) return false;
170:     if (dist > 0.001) {
171:       const dot = (dx / dist) * Math.sin(facing) + (dz / dist) * Math.cos(facing);
172:       if (dot < 0.05) return false;
173:     }
174:     return true;
175:   }
176: 
177:   pop() {
178:     if (!this.alive) return;
179:     this.alive = false;
180:     this.cooldown = 4.5;
181:     this.group.visible = false;
182:   }
183: 
184:   update(dt) {
185:     this.time += dt;
186:     if (!this.alive) {
187:       this.cooldown -= dt;
188:       if (this.cooldown <= 0) {
189:         this.alive = true;
190:         this.group.visible = true;
191:         this.group.scale.setScalar(0.01);
192:       }
193:       return;
194:     }
195:     const targetScale = this.group.scale.x < 1 ? Math.min(1, this.group.scale.x + dt * 4.5) : 1;
196:     this.group.scale.setScalar(targetScale);
197:     this.position.y = this.home.y + Math.sin(this.time * 2.0 + this.phase) * 0.18;
198:     this.group.position.copy(this.position);
199:     this.core.rotation.y += dt * 1.4;
200:     this.core.rotation.z = Math.sin(this.time * 0.9) * 0.22;
201:     this.ring.rotation.z += dt * 0.8;
202:     const pulse = 0.82 + Math.sin(this.time * 3.2) * 0.18;
203:     this.glow.material.opacity = 0.36 * pulse;
204:     this.light.intensity = 0.9 * pulse;
205:     this.ringMat.opacity = 0.35 * pulse;
206:   }
207: }
