1192:   clipCamera(focus, desired) {
1193:     const dir = desired.clone().sub(focus);
1194:     const len = dir.length();
1195:     if (len < 0.001) return desired;
1196:     dir.divideScalar(len);
1197:     const ray = new THREE.Ray(focus, dir);
1198:     const hit = new THREE.Vector3();
1199:     let nearest = len;
1200:     for (const collider of this.world.colliders) {
1201:       if (!collider.active || !collider.box) continue;
1202:       if (collider.box.containsPoint(focus)) continue;
1203:       if (!ray.intersectBox(collider.box, hit)) continue;
1204:       const d = hit.distanceTo(focus);
1205:       if (d > 0.25 && d < nearest) nearest = d;
1206:     }
1207:     if (nearest < len - 0.05) {
1208:       desired.copy(focus).addScaledVector(dir, Math.max(1.1, nearest - 0.3));
1209:     }
1210:     return desired;
1211:   }
