1213:   updateMenuCamera(dt, snap = false) {
1214:     this.menuTime += dt;
1215:     const t = this.menuTime;
1216:     const focus = new THREE.Vector3(0, 2.35, 6.8);
1217:     const yaw = 0.45 + t * 0.07;
1218:     const pitch = 0.16 + Math.sin(t * 0.11) * 0.025;
1219:     const dist = 10.5;
1220:     const desired = new THREE.Vector3(
1221:       focus.x + Math.sin(yaw) * Math.cos(pitch) * dist,
1222:       focus.y + Math.sin(pitch) * dist,
1223:       focus.z + Math.cos(yaw) * Math.cos(pitch) * dist
