90:       velocity: velocity.clone(), gravity, homing,
91:     });
92:   }
93: 
94:   update(dt, player) {
95:     const active = !!player && !player.dead;
96:     const playerCenter = player ? player.center : null;
97:     for (let i = this.list.length - 1; i >= 0; i--) {
98:       const p = this.list[i];
99:       p.age += dt;
100: 
101:       if (p.homing > 0 && active) {
102:         const to = playerCenter.clone().sub(p.mesh.position);
103:         const d = to.length();
104:         if (d > 0.001) {
105:           const speed = p.velocity.length();
106:           const desired = to.divideScalar(d).multiplyScalar(speed);
107:           const k = clamp(p.homing * dt, 0, 1);
108:           p.velocity.lerp(desired, k);
109:         }
110:       }
111:       if (p.gravity) p.velocity.y -= p.gravity * dt;
112:       p.mesh.position.addScaledVector(p.velocity, dt);
113:       p.mesh.rotation.x += dt * 7;
114:       p.mesh.rotation.y += dt * 9;
115:       p.glow.material.opacity = 0.55 + Math.sin(p.age * 18) * 0.2;
116: 
117:       let remove = p.age >= p.life;
118: 
119:       if (!remove && active) {
120:         const dx = p.mesh.position.x - playerCenter.x;
121:         const dy = p.mesh.position.y - playerCenter.y;
122:         const dz = p.mesh.position.z - playerCenter.z;
123:         if (dx * dx + dy * dy + dz * dz < (p.radius + 0.78) * (p.radius + 0.78)) {
124:           player.takeDamage(p.damage, p.mesh.position, { knockback: 6.5, up: 4.0, iframes: 1.0 });
125:           this.effects.burst(p.mesh.position, {
126:             count: 16, speed: 5, size: 0.18, life: 0.4,
127:             colors: [p.color, 0xffffff], gravity: 0,
128:           });
129:           remove = true;
130:         }
131:       }
132: 
133:       if (!remove && (p.mesh.position.y < -70 || p.mesh.position.y > 120)) remove = true;
134: 
135:       if (remove) this._remove(i);
136:     }
137:   }
138: 
139:   _remove(i) {
140:     const p = this.list[i];
141:     this.scene.remove(p.mesh);
142:     p.mat.dispose();
143:     p.glow.material.dispose();
144:     this.list.splice(i, 1);
145:   }
146: 
147:   clear() {
148:     for (let i = this.list.length - 1; i >= 0; i--) this._remove(i);
149:   }
150: }
