152: /* ============================================================
153:    Regular enemies
154:    ============================================================ */
155: class Enemy {
156:   constructor(game, spec) {
157:     this.game = game;
158:     this.scene = game.scene;
159:     this.world = game.world;
160:     this.effects = game.effects;
161:     this.zone = spec.zone;
162:     this.type = spec.type;
163:     this.variant = spec.variant || spec.zone;
164:     this.palette = PALETTES[this.variant] || PALETTES.meadow;
165:     this.stats = TYPE_STATS[this.type] || TYPE_STATS.mossling;
166:     this.name = this.stats.name;
167:     this.color = this.palette.orb;
168: 
169:     this.home = spec.position.clone();
170:     this.position = spec.position.clone();
171:     this.velocity = V3();
172:     this.radius = this.stats.radius;
173:     this.maxHp = this.stats.hp;
174:     this.hp = this.maxHp;
175:     this.alive = true;
176:     this.dying = 0;
177:     this.hitFlash = 0;
178:     this.time = rand(0, 10);
179:     this.hitCooldown = 0;
180:     this.attackCooldown = rand(0.8, 2.2);
181:     this.patrolRadius = spec.patrol || 0;
182:     this.wanderAngle = rand(0, TAU);
183:     this.wanderTimer = rand(1.5, 3.5);
184:     this.aggro = false;
185:     this.state = 'idle';
186:     this.facing = rand(0, TAU);
187:     this.chargeTimer = 0;
188:     this.charging = false;
189: 
190:     this.group = new THREE.Group();
191:     this.group.position.copy(this.position);
192:     this.scene.add(this.group);
193: 
194:     this._build();
195:   }
196: 
197:   get center() {
198:     const h = this.type === 'wisp' ? 0.6 : this.type === 'sentry' ? 1.25 : 0.72;
199:     return this.position.clone().add(V3(0, h, 0));
200:   }
201: 
202:   /* ---------------- visuals ---------------- */
203:   _build() {
204:     const p = this.palette;
205:     if (this.type === 'wisp') this._buildWisp(p);
206:     else if (this.type === 'sentry') this._buildSentry(p);
207:     else this._buildMossling(p);
208:     this.group.traverse((o) => {
209:       if (o.isMesh) { o.castShadow = true; o.receiveShadow = false; }
210:     });
211:   }
212: 
213:   _buildMossling(p) {
214:     const bodyMat = new THREE.MeshStandardMaterial({
215:       color: p.body, roughness: 0.92, metalness: 0.02,
216:       emissive: new THREE.Color(p.dark).multiplyScalar(0.18), emissiveIntensity: 0.4,
217:       envMapIntensity: 0.7,
218:     });
219:     const darkMat = new THREE.MeshStandardMaterial({ color: p.dark, roughness: 0.95 });
220:     const leafMat = new THREE.MeshStandardMaterial({
221:       color: p.leaf, roughness: 0.85, flatShading: true,
222:       emissive: new THREE.Color(p.leaf).multiplyScalar(0.1), emissiveIntensity: 0.4,
223:     });
224:     const eyeMat = new THREE.MeshBasicMaterial({ color: p.eye, toneMapped: false });
225: 
226:     const body = new THREE.Mesh(new THREE.SphereGeometry(0.55, 14, 10), bodyMat);
227:     body.scale.set(1.05, 0.9, 0.95);
228:     body.position.y = 0.7;
229:     this.group.add(body);
230:     this.body = body;
231: 
232:     // mossy back and head crown
233:     for (let i = 0; i < 5; i++) {
234:       const leaf = new THREE.Mesh(new THREE.ConeGeometry(rand(0.1, 0.2), rand(0.24, 0.5), 4), leafMat);
235:       leaf.position.set(rand(-0.4, 0.4), 1.08 + rand(-0.05, 0.18), rand(-0.3, 0.3));
236:       leaf.rotation.z = rand(-0.5, 0.5);
237:       leaf.rotation.x = rand(-0.4, 0.4);
238:       this.group.add(leaf);
239:     }
240: 
241:     const snout = new THREE.Mesh(new THREE.SphereGeometry(0.25, 10, 8), darkMat);
242:     snout.scale.set(1, 0.7, 1.2);
243:     snout.position.set(0, 0.66, 0.42);
244:     this.group.add(snout);
245: 
246:     for (const sx of [-0.19, 0.19]) {
247:       const eye = new THREE.Mesh(new THREE.SphereGeometry(0.085, 8, 6), eyeMat);
248:       eye.position.set(sx, 0.86, 0.4);
249:       this.group.add(eye);
250:     }
251: 
252:     for (const sx of [-1, 1]) {
253:       const leg = new THREE.Mesh(new THREE.CapsuleGeometry(0.13, 0.26, 3, 6), darkMat);
254:       leg.position.set(sx * 0.3, 0.25, 0);
255:       this.group.add(leg);
256:       const arm = new THREE.Mesh(new THREE.CapsuleGeometry(0.1, 0.3, 3, 6), bodyMat);
257:       arm.position.set(sx * 0.56, 0.66, 0.12);
258:       arm.rotation.z = sx * 0.4;
259:       this.group.add(arm);
260:     }
261: 
262:     const glow = makeGlowSprite({ color: p.orb, size: 2.2, opacity: 0.24, texture: GLOW });
263:     glow.position.y = 0.75;
264:     this.group.add(glow);
265:     this.glow = glow;
266:   }
267: 
268:   _buildWisp(p) {
269:     this.coreMat = new THREE.MeshStandardMaterial({
270:       color: p.orb, emissive: new THREE.Color(p.orb).multiplyScalar(0.7),
271:       emissiveIntensity: 2.2, roughness: 0.15, metalness: 0.1,
272:       transparent: true, opacity: 0.95,
273:     });
274:     const core = new THREE.Mesh(new THREE.OctahedronGeometry(0.34, 0), this.coreMat);
275:     core.position.y = 0.6;
276:     this.group.add(core);
277:     this.core = core;
278: 
279:     const shellMat = new THREE.MeshBasicMaterial({
280:       color: p.eye, transparent: true, opacity: 0.32, blending: THREE.AdditiveBlending,
281:       depthWrite: false, toneMapped: false, wireframe: true,
282:     });
283:     const shell = new THREE.Mesh(new THREE.IcosahedronGeometry(0.66, 1), shellMat);
284:     shell.position.y = 0.6;
285:     this.group.add(shell);
286:     this.shell = shell;
287: 
288:     this.ringMat = new THREE.MeshBasicMaterial({
289:       color: p.orb, transparent: true, opacity: 0.55,
290:       blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
291:     });
292:     this.ring = new THREE.Mesh(new THREE.TorusGeometry(0.88, 0.025, 4, 32), this.ringMat);
293:     this.ring.rotation.x = Math.PI / 2.4;
294:     this.ring.position.y = 0.6;
295:     this.group.add(this.ring);
296: 
297:     this.ring2 = new THREE.Mesh(new THREE.TorusGeometry(0.6, 0.018, 4, 24), this.ringMat);
298:     this.ring2.rotation.y = Math.PI / 2.2;
299:     this.ring2.position.y = 0.6;
300:     this.group.add(this.ring2);
301: 
302:     this.glow = makeGlowSprite({ color: p.orb, size: 2.8, opacity: 0.42, texture: GLOW });
303:     this.glow.position.y = 0.6;
304:     this.group.add(this.glow);
305: 
306:     this.light = new THREE.PointLight(p.orb, 1.0, 9, 2);
307:     this.light.position.y = 0.6;
308:     this.group.add(this.light);
309:   }
310: 
311:   _buildSentry(p) {
312:     const stoneMat = new THREE.MeshStandardMaterial({
313:       color: p.stone, roughness: 0.9, metalness: 0.05,
314:       emissive: new THREE.Color(p.dark).multiplyScalar(0.2), emissiveIntensity: 0.4,
315:       envMapIntensity: 0.7,
316:     });
317:     const coreMat = new THREE.MeshStandardMaterial({
318:       color: p.orb, emissive: new THREE.Color(p.orb).multiplyScalar(0.8),
319:       emissiveIntensity: 2.4, roughness: 0.12, metalness: 0.15,
320:     });
321:     this.coreMat = coreMat;
322: 
323:     const base = new THREE.Mesh(new THREE.CylinderGeometry(0.48, 0.66, 0.5, 6), stoneMat);
324:     base.position.y = 0.3;
325:     this.group.add(base);
326:     const body = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.5, 1.0, 6), stoneMat);
327:     body.position.y = 1.0;
328:     this.group.add(body);
329:     this.body = body;
330:     const head = new THREE.Mesh(new THREE.OctahedronGeometry(0.4, 0), stoneMat);
331:     head.position.y = 1.72;
332:     this.group.add(head);
333:     this.head = head;
334: 
335:     const core = new THREE.Mesh(new THREE.OctahedronGeometry(0.19, 0), coreMat);
336:     core.position.set(0, 1.02, 0.35);
337:     this.group.add(core);
338:     this.core = core;
339: 
340:     this.ringMat = new THREE.MeshBasicMaterial({
341:       color: p.orb, transparent: true, opacity: 0.6,
342:       blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
343:     });
344:     this.ring = new THREE.Mesh(new THREE.TorusGeometry(0.8, 0.03, 4, 28), this.ringMat);
345:     this.ring.rotation.x = Math.PI / 2;
346:     this.ring.position.y = 1.72;
347:     this.group.add(this.ring);
348: 
349:     this.glow = makeGlowSprite({ color: p.orb, size: 2.6, opacity: 0.34, texture: GLOW });
350:     this.glow.position.y = 1.15;
351:     this.group.add(this.glow);
352: 
353:     this.light = new THREE.PointLight(p.orb, 0.8, 10, 2);
354:     this.light.position.y = 1.15;
355:     this.group.add(this.light);
356: 
357:     // two floating side tablets
358:     const tabMat = new THREE.MeshStandardMaterial({ color: p.stone, roughness: 0.85, metalness: 0.1 });
359:     this.tablets = [];
360:     for (const sx of [-1, 1]) {
361:       const tab = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.7, 0.34), tabMat);
362:       tab.position.set(sx * 0.78, 1.18, 0);
363:       this.group.add(tab);
364:       this.tablets.push(tab);
365:     }
366:   }
367: 
368:   /* ---------------- combat ---------------- */
369:   tryHit(playerPos, facing) {
370:     if (!this.alive) return false;
371:     const c = this.center;
372:     const dx = c.x - playerPos.x;
373:     const dz = c.z - playerPos.z;
374:     const dist = Math.hypot(dx, dz);
375:     if (dist > this.stats.reach + 1.15) return false;
376:     if (Math.abs(c.y - (playerPos.y + 1.0)) > (this.type === 'sentry' ? 2.5 : 2.2)) return false;
377:     if (dist > 0.001) {
378:       const dot = (dx / dist) * Math.sin(facing) + (dz / dist) * Math.cos(facing);
379:       if (dot < -0.05) return false;
380:     }
381:     return true;
382:   }
383: 
384:   takeDamage(amount = 1, source = null) {
385:     if (!this.alive) return false;
386:     this.hp -= amount;
387:     this.hitFlash = 0.16;
388:     if (source) {
389:       const dir = this.position.clone().sub(source);
390:       dir.y = 0;
391:       if (dir.lengthSq() > 0.001) {
392:         dir.normalize();
393:         this.velocity.addScaledVector(dir, this.type === 'mossling' ? 2.6 : 0.8);
394:       }
395:     }
396:     if (this.hp <= 0) {
397:       this._die();
398:       return true;
399:     }
400:     return false;
401:   }
402: 
403:   _die() {
404:     if (!this.alive) return;
405:     this.alive = false;
406:     this.dying = 0.55;
407:     this.effects.enemyDeath(this.center, this.color);
408:     this.game.sfx('enemyDie');
409:     this.game.onEnemyKilled?.(this);
410:     if (this.light) this.light.intensity = 0;
411:   }
412: 
413:   /* ---------------- simulation ---------------- */
414:   update(dt, player) {
415:     this.time += dt;
416:     this.hitCooldown = Math.max(0, this.hitCooldown - dt);
417:     this.attackCooldown = Math.max(0, this.attackCooldown - dt);
418:     if (this.hitFlash > 0) this.hitFlash -= dt;
419: 
420:     if (!this.alive) {
421:       this.dying -= dt;
422:       const k = clamp(this.dying / 0.55, 0, 1);
423:       this.group.scale.setScalar(Math.max(0.001, k));
424:       this.group.rotation.y += dt * 3;
425:       if (this.dying <= 0) this.group.visible = false;
426:       return;
427:     }
428: 
429:     const toPlayer = player.position.clone().sub(this.position);
430:     const dist = Math.hypot(toPlayer.x, toPlayer.z);
431:     const vertical = Math.abs(this.position.y - player.position.y);
432: 
433:     if (this.type === 'mossling') this._updateMossling(dt, player, dist, vertical);
434:     else if (this.type === 'wisp') this._updateWisp(dt, player, dist, vertical);
435:     else this._updateSentry(dt, player, dist, vertical);
436: 
437:     // visual response to damage
438:     const flash = this.hitFlash > 0 ? 1 + this.hitFlash * 2.4 : 1;
439:     this.group.scale.setScalar(this.type === 'mossling' ? flash : 1);
440:     if (this.coreMat) this.coreMat.emissiveIntensity = 2.0 + Math.sin(this.time * 4) * 0.35 + (this.hitFlash > 0 ? 2.5 : 0);
441:     if (this.glow) this.glow.material.opacity = 0.28 + Math.sin(this.time * 2.6 + 1) * 0.08;
442: 
443:     this.group.position.copy(this.position);
444:   }
445: 
446:   _updateMossling(dt, player, dist, vertical) {
447:     const aggro = dist < 14 && vertical < 7;
448:     this.aggro = aggro;
449: 
450:     if (aggro) {
451:       const dir = player.position.clone().sub(this.position);
452:       dir.y = 0;
453:       if (dir.lengthSq() > 0.001) dir.normalize();
454:       this.facing = Math.atan2(dir.x, dir.z);
455: 
456:       const moving = dist > 1.9;
457:       if (moving) {
458:         const speed = this.stats.speed * (this.charging ? 2.1 : 1);
459:         this.velocity.x = damp(this.velocity.x, dir.x * speed, 8, dt);
460:         this.velocity.z = damp(this.velocity.z, dir.z * speed, 8, dt);
461:       } else {
462:         this.velocity.x = damp(this.velocity.x, 0, 10, dt);
463:         this.velocity.z = damp(this.velocity.z, 0, 10, dt);
464:       }
465: 
466:       // close-range lunge telegraph
467:       if (dist < 3.6 && this.attackCooldown <= 0) {
468:         this.attackCooldown = 2.1;
469:         this.charging = true;
470:         this.chargeTimer = 0.42;
471:         this.velocity.x = dir.x * 11.5;
472:         this.velocity.z = dir.z * 11.5;
473:       }
474: 
475:       if (dist < 1.65 && vertical < 2.0 && this.hitCooldown <= 0) {
476:         this.hitCooldown = 1.0;
477:         player.takeDamage(1, this.center, { knockback: 7, up: 4.5 });
478:       }
479:     } else {
480:       // slow patrol orbit around home
481:       this.wanderTimer -= dt;
482:       if (this.wanderTimer <= 0) {
483:         this.wanderTimer = rand(2.2, 4.4);
484:         this.wanderAngle = rand(0, TAU);
485:       }
486:       const radius = Math.max(0.6, this.patrolRadius);
487:       const target = this.home.clone().add(V3(
488:         Math.cos(this.wanderAngle) * radius * 0.7,
489:         0,
490:         Math.sin(this.wanderAngle) * radius * 0.7,
491:       ));
492:       const dir = target.clone().sub(this.position);
493:       dir.y = 0;
494:       if (dir.lengthSq() > 0.15) {
495:         dir.normalize();
496:         const speed = 1.15;
497:         this.velocity.x = damp(this.velocity.x, dir.x * speed, 5, dt);
498:         this.velocity.z = damp(this.velocity.z, dir.z * speed, 5, dt);
499:         this.facing = Math.atan2(dir.x, dir.z);
500:       } else {
501:         this.velocity.x = damp(this.velocity.x, 0, 6, dt);
502:         this.velocity.z = damp(this.velocity.z, 0, 6, dt);
503:       }
504:     }
505: 
506:     this.chargeTimer = Math.max(0, this.chargeTimer - dt);
507:     if (this.chargeTimer <= 0) this.charging = false;
508: 
509:     const nextX = this.position.x + this.velocity.x * dt;
510:     const nextZ = this.position.z + this.velocity.z * dt;
511:     if (!this.world.inWater(V3(nextX, this.position.y + 0.4, nextZ))) {
512:       this.position.x = nextX;
513:       this.position.z = nextZ;
514:     } else {
515:       this.velocity.x = 0;
516:       this.velocity.z = 0;
517:     }
518:     this.position.y = groundHeight(this.world, this.position, 1.2);
519: 
520:     this.group.rotation.y = this.facing;
521:     const speed = Math.hypot(this.velocity.x, this.velocity.z);
522:     const bob = Math.sin(this.time * (speed > 0.4 ? 10 : 2.4)) * (speed > 0.4 ? 0.06 : 0.03);
523:     if (this.body) this.body.position.y = 0.7 + bob;
524:     this.group.rotation.z = clamp(-this.velocity.x * 0.008, -0.08, 0.08);
525:   }
526: 
527:   _updateWisp(dt, player, dist, vertical) {
528:     const aggro = dist < 19 && vertical < 10;
529:     this.aggro = aggro;
530:     const orbitRadius = aggro ? 7.2 : Math.max(2.5, this.patrolRadius || 3);
531:     const target = aggro
532:       ? player.position.clone().add(V3(
533:         Math.cos(this.time * 0.75) * orbitRadius,
534:         3.4 + Math.sin(this.time * 1.1) * 0.6,
535:         Math.sin(this.time * 0.75) * orbitRadius,
536:       ))
537:       : this.home.clone().add(V3(
538:         Math.cos(this.time * 0.5) * orbitRadius,
539:         0.4 + Math.sin(this.time * 1.4) * 0.7,
540:         Math.sin(this.time * 0.5) * orbitRadius,
541:       ));
542: 
543:     this.position.lerp(target, 1 - Math.exp(-1.8 * dt));
544:     if (aggro) {
545:       const look = player.position.clone().sub(this.position);
546:       this.facing = Math.atan2(look.x, look.z);
547:       this.group.rotation.y = this.facing;
548: 
549:       if (this.attackCooldown <= 0 && dist < 17) {
550:         this.attackCooldown = rand(2.3, 3.3);
551:         const origin = this.center;
552:         const aim = player.center.clone().sub(origin).normalize();
553:         const speed = 12.5;
554:         this.game.projectiles.spawn({
555:           position: origin,
556:           velocity: aim.multiplyScalar(speed),
557:           color: this.palette.orb,
558:           radius: 0.19,
559:           damage: 1,
560:           life: 2.2,
561:           glowScale: 1.1,
562:         });
563:         this.game.sfx('shoot', 0.7);
564:         this.game.effects.burst(origin, {
565:           count: 8, speed: 2.5, size: 0.12, life: 0.3, colors: [this.palette.orb, 0xffffff],
566:         });
567:       }
568:     }
569: 
570:     this.core.rotation.y += dt * 2.2;
571:     this.core.rotation.z = Math.sin(this.time * 1.2) * 0.18;
572:     this.shell.rotation.y -= dt * 0.8;
573:     this.shell.rotation.x += dt * 0.4;
574:     this.ring.rotation.z += dt * 1.5;
575:     this.ring2.rotation.x += dt * 1.1;
576:     const p = 0.9 + Math.sin(this.time * 3) * 0.1;
577:     this.light.intensity = 0.9 * p;
578:   }
579: 
580:   _updateSentry(dt, player, dist, vertical) {
581:     const aggro = dist < 21 && vertical < 9;
582:     this.aggro = aggro;
583:     if (aggro) {
584:       const look = player.position.clone().sub(this.position);
585:       this.facing = Math.atan2(look.x, look.z);
586:     }
587:     this.group.rotation.y = damp(this.group.rotation.y, this.facing, 4, dt);
588: 
589:     // hover / idle
590:     this.position.y = this.home.y + Math.sin(this.time * 1.3) * 0.08;
591:     if (this.tablets) {
592:       this.tablets.forEach((t, i) => {
593:         t.rotation.y += dt * (i ? 1.2 : -1.2);
594:         t.position.y = 1.18 + Math.sin(this.time * 1.8 + i * Math.PI) * 0.12;
595:       });
