440:     if (a.kind === 'slam') {
441:       if (a.t <= 0 && !a.done) {
442:         a.done = true;
443:         this.group.rotation.y = Math.atan2(
444:           player.position.x - this.position.x,
445:           player.position.z - this.position.z,
