458:       }
459:       return;
460:     }
461: 
462:     if (a.kind === 'boulder') {
463:       if (a.t <= 0 && !a.done) {
464:         a.done = true;
465:         this.game.sfx('shoot');
466:         const origin = this.center.clone().add(V3(0, 0.9, 0));
