472:             position: origin.clone(),
473:             velocity: V3(Math.sin(ang) * 12, 4.5, Math.cos(ang) * 12),
474:             color: 0xc7a36a, radius: 0.38, damage: 1, life: 3.0,
475:             gravity: 12, glowScale: 1.4,
476:           });
477:         }
478:         this._finishAction(2.5);
479:       }
480:       return;
481:     }
482: 
483:     if (a.kind === 'charge') {
484:       if (!a.done && a.t <= 0) {
485:         a.done = true;
486:         const dir = player.position.clone().sub(this.position);
487:         dir.y = 0;
